+gob_data_set_default(gob_data_t *data) {
+    data->is_default = true;
+}
+
+bool
+gob_data_is_default(gob_data_t *data) {
+    return data->is_default;
+}
+
+// Associative array
+static gob_data_t *
+gob_data_associative_array(wmem_allocator_t *allocator,
+                           gob_data_type_t data_type, int64_t type_id) {
+    gob_data_associative_array_t *associative_array =
+        wmem_new0(allocator, gob_data_associative_array_t);
+
+    if (!associative_array) {
+        return NULL;
+    }
+
+    gob_data_init(&associative_array->data, data_type, type_id);
+
+    associative_array->map =
+        wmem_map_new(allocator, g_direct_hash, g_direct_equal);
+
+    associative_array->ordered_list = wmem_list_new(allocator);
+
+    associative_array->allocator = allocator;
+
+    return &associative_array->data;
+}
+
+static gob_data_t *
+gob_data_associative_array_get(const gob_data_t *data, const gob_data_t *key) {
+    if (!key) {
+        return NULL;
+    }
+
+    gob_data_associative_array_t *associative_array =
+        gob_data_to_associative_array(data);
+
+    return wmem_map_lookup(associative_array->map, key);
+}
+
+static bool
+gob_data_associative_array_set(gob_data_t *data, const gob_data_t *key,
+                               gob_data_t *value) {
+    if (!value) {
+        return false;
+    }
+
+    if (!key || data == value) {
+        return false;
+    }
+
+    gob_data_associative_array_t *associative_array =
+        gob_data_to_associative_array(data);
+
+    if (wmem_map_lookup(associative_array->map, key) != NULL) {
+        // Key is already present. Do nothing.
+        return true;
+    }
+
+    wmem_map_insert(associative_array->map, key, value);
+
+    wmem_list_append(associative_array->ordered_list, (gob_data_t *)key);
+
+    return true;
+}
+
+static size_t
+gob_data_associative_array_size(const gob_data_t *data) {
+    gob_data_associative_array_t *associative_array =
+        gob_data_to_associative_array(data);
+
+    return wmem_map_size(associative_array->map);
+}
+
