+}
+
+// Container iterator
+gob_data_iterator_t *
+gob_data_iter(gob_data_t *data) {
+    if (!gob_data_is_slice(data) && !gob_data_is_array(data) &&
+        !gob_data_is_struct(data) && !gob_data_is_map(data)) {
+        return NULL;
+    }
+
+    wmem_allocator_t *allocator;
+    gob_data_associative_array_t *associative_array = NULL;
