+    gob_data_iterator_t *iter =
+        wmem_new0(allocator, gob_data_iterator_t);
+
+    iter->magic = GOB_DATA_ITERATOR_MAGIC;
+    iter->data = data;
+
+    if (gob_data_is_slice(data) || gob_data_is_array(data)) {
+        iter->ptr = GUINT_TO_POINTER(0);
+
+        return iter;
+    }
+
+    iter->ptr = wmem_list_head(associative_array->ordered_list);
+
+    return iter;
+}
+
+gob_data_iterator_t *
+gob_data_iter_next(gob_data_iterator_t *iter) {
+    if (iter == NULL) {
+        return NULL;
+    }
+
+    if (iter->magic != GOB_DATA_ITERATOR_MAGIC) {
+        return NULL;
+    }
+
+    if (gob_data_is_slice(iter->data) ||
+        gob_data_is_array(iter->data)) {
+        gob_data_array_t *array = gob_data_to_array(iter->data);
+
+        unsigned int array_size = GPOINTER_TO_UINT(iter->ptr);
+
+        if (array_size >= array->entries) {
+            return NULL;
+        }
+
+        iter->ptr = GUINT_TO_POINTER(++array_size);
+
+        return iter;
+    }
+
+    if (!gob_data_is_struct(iter->data) &&
+        !gob_data_is_map(iter->data)) {
+        return NULL;
+    }
+
+    if (!iter->ptr) {
+        return NULL;
+    }
+
+    iter->ptr = wmem_list_frame_next((wmem_list_frame_t *)iter->ptr);
+
+    return iter;
+}
+
+gob_data_t *
+gob_data_iter_value(gob_data_iterator_t *iter) {
+    if (iter == NULL) {
+        return NULL;
+    }
