+
+// Array
+static gob_data_t *
+gob_data_base_array(wmem_allocator_t *allocator, gob_data_type_t data_type,
+                    int64_t type_id) {
+    gob_data_array_t *array = wmem_new0(allocator, gob_data_array_t);
+
+    if (!array) {
+        return NULL;
+    }
+
+    gob_data_init(&array->data, data_type, type_id);
+
+    array->allocator = allocator;
+    array->entries = 0;
+    array->size = 8;
+
+    array->table = wmem_alloc(allocator, array->size * sizeof(gob_data_t *));
+    if (!array->table) {
+        wmem_free(allocator, array);
+        return NULL;
+    }
+
+    return &array->data;
+}
+
+static size_t
+gob_data_array_size_safe(const gob_data_t *data) {
+    return gob_data_to_array(data)->entries;
+}
+
+static gob_data_t *
+gob_data_array_get_safe(const gob_data_t *data, size_t index) {
+    gob_data_array_t *array = gob_data_to_array(data);
+
+    if (index >= array->entries)
+        return NULL;
+
+    return array->table[index];
+}
+
+static gob_data_t **
+gob_data_array_grow(gob_data_array_t *array, size_t amount) {
+    size_t new_size;
+    gob_data_t **old_table, **new_table;
+
+    if (array->entries + amount <= array->size) {
+        return array->table;
+    }
+
+    old_table = array->table;
+
+    new_size = MAX(array->size + amount, array->size * 2);
+    new_table = wmem_realloc(array->allocator, old_table,
+                             new_size * sizeof(gob_data_t *));
+    if (!new_table)
+        return NULL;
+
+    array->size = new_size;
+    array->table = new_table;
+
+    return array->table;
+}
+
+static int
+gob_data_array_append_safe(gob_data_t *data, gob_data_t *value) {
+    if (!value || data == value) {
+        return -1;
+    }
+
+    gob_data_array_t *array = gob_data_to_array(data);
+
+    if (!gob_data_array_grow(array, 1)) {
+        return -1;
+    }
+
+    array->table[array->entries] = value;
+    array->entries++;
+
+    return 0;
+}
+
+gob_data_t *
