+    if (!gob_data_is_array(data)) {
+        return -1;
+    }
+
+    return gob_data_array_append_safe(data, value);
+}
+
+// Slice
+gob_data_t *
+gob_data_slice(wmem_allocator_t *allocator, int64_t type_id) {
+    return gob_data_base_array(allocator, GOB_TYPE_SLICE, type_id);
+}
